use baal_service::{Config,Service,HttpServer,storage::{read_json,journal_rows},now,need_network_configuration};
use baal_transport_service::{Transport,SystemClock,WindowsDpapiCredentials};
use std::{path::PathBuf,thread,time::Duration};
fn run()->Result<(),String>{let args:Vec<String>=std::env::args().skip(1).collect();let get=|key:&str|args.iter().position(|x|x==key).and_then(|i|args.get(i+1)).cloned();if let Some(observer_file)=get("--observer-config"){if !args.iter().any(|a|a=="--consume-once")||args.iter().any(|a|a=="--read-only-network"||a=="--serve"||a=="--config"||a=="--replay"){return Err("OBSERVER_CAPTURE_ONLY_ONESHOT_REQUIRED".into())}let observer_path=PathBuf::from(observer_file);if !observer_path.is_absolute(){return Err("OBSERVER_CONFIG_PATH_ABSOLUTE_REQUIRED".into())}let config:baal_service::paper_observer::ObserverConfig=serde_json::from_value(read_json(&observer_path)?).map_err(|_|"OBSERVER_CONFIG")?;let maximum=get("--maximum-rows").map(|v|v.parse::<usize>().map_err(|_|"OBSERVER_ROW_BOUND".to_owned())).transpose()?.unwrap_or(4096);if maximum==0||maximum>4096{return Err("OBSERVER_ROW_BOUND".into())}let mut observer=baal_service::paper_observer::Observer::open(config)?;let status=observer.consume_once(&now(),maximum)?;println!("{}",serde_json::json!({"mode":"rust_capture_only_paper_observer","completed":true,"bankHash":status["bankHash"],"sourceSequence":status["sourceSequence"],"journalSequence":status["journalSequence"],"consumedRows":status["consumedRows"],"networkRequests":0,"competitionOrders":0,"profitabilityEstablished":false}));return Ok(())}let path=PathBuf::from(get("--config").ok_or("SERVICE_CONFIG_REQUIRED")?);let config:Config=serde_json::from_value(read_json(&path)?).map_err(|_|"SERVICE_CONFIGURATION")?;config.validate()?;let live=config.mode=="network_read_only";if live{need_network_configuration(&config,args.iter().any(|a|a=="--read-only-network"))?;}let mut service=Service::open(config)?;let _server=if args.iter().any(|a|a=="--serve"){Some(HttpServer::start(service.config.port,service.derived.clone())?)}else{None};if let Some(replay)=get("--replay"){if live{return Err("SERVICE_LIVE_REPLAY_MIXING_DENIED".into())}journal_rows(&PathBuf::from(replay),|row|{let account=row.get("accountEligibility").cloned();let source=row.get("publication").cloned().unwrap_or(row);service.ingest(source,account)})?;}if live{let scope=service.transport_scope();let authority=service.read_authority(service.config.migration.clone());let transport_config=baal_transport_service::Config{queue_dir:service.config.runtime_dir.join("account-queue"),account_scope:format!("Codex:{}",service.config.tournament_id),scope,maximum_pages:100,writes_enabled:false};let fresh_queue=!service.config.runtime_dir.join("account-queue/account-queue.jsonl").exists()&&!service.config.runtime_dir.join("account-queue/account-queue-manifest.json").exists();let credentials=WindowsDpapiCredentials::approved_default().map_err(|e|e.code)?;let mut transport=Transport::new(transport_config,Box::new(credentials),Box::new(SystemClock),Box::new(authority)).map_err(|e|e.code)?;if fresh_queue{let rate=read_json(&service.config.migration.as_ref().unwrap().legacy_rate_path)?;transport.reserve_legacy_migration_boundary(rate["next"].as_u64().unwrap_or(0),rate["manualReview"]==true||rate["next"].is_null()).map_err(|e|e.code)?;}service.start_session(&now())?;let cycles=get("--cycles").map(|x|x.parse::<u64>().map_err(|_|"SERVICE_CYCLE_BOUND".to_owned())).transpose()?.unwrap_or(u64::MAX);for _ in 0..cycles{service.guard()?;service.collect_cycle(&mut transport)?;}}else if args.iter().any(|a|a=="--serve"){while service.guard().is_ok(){service.publish(&now())?;thread::sleep(Duration::from_millis(500));}}println!("{}",serde_json::json!({"status":"completed","language":"Rust","publications":service.cycles,"competitionOrders":0,"profitabilityEstablished":false}));Ok(())}
fn main(){if let Err(error)=run(){eprintln!("{error}");std::process::exit(1)}}
